mapper.select:
select id , warning_grade as warningGrade from tb_early_warning where node_id =#{nodeId} and is_affirm = 2

    and warning_type =#{warningType}

limit 1;

select
warning_type as warningType,
warning_grade as warningGrade,
COUNT(warning_grade='1' OR NULL) AS oneWarningCount,
COUNT(warning_grade='2' OR NULL) AS twoWarningCount,
COUNT(warning_grade='3' OR NULL) AS threeWarningCount
from tb_early_warning
where is_affirm = '2'
 and warning_type = #{earlyWarningDto.warningType} 
 and principal_name = #{earlyWarningDto.principalName} 
 and warning_time >= #{earlyWarningDto.startTime}
 and warning_time <= #{earlyWarningDto.startTime}
group by warning_type,warning_grade

SELECT
t1.node_id,t1.warning_type,t1.warning_grade,t1.warning_val,t1.principal_name,t1.deal_suggestion,t1.deal_time,t1.remark,t1.area_id,t1.stack_id,
(CASE
WHEN (stack_id IS NULL ) THEN (SELECT site_name FROM tb_ware_area t WHERE t.id = t1.area_id)
WHEN (area_id IS NULL) THEN (SELECT site_name FROM tb_stack t WHERE t.id = t1.stack_id) END) AS siteName
FROM tb_early_warning t1
WHERE t1.is_deal = '1'
and t1.warning_type = #{earlyWarningDto.warningType}
and t1.warning_grade = #{earlyWarningDto.warningGrade}
and t1.node_id = #{earlyWarningDto.nodeId}
and t1.principal_name = #{earlyWarningDto.principalName}
and t1.deal_time >= #{earlyWarningDto.startTime}
and t1.deal_time <= #{earlyWarningDto.endTime}
ORDER BY t1.area_id DESC,t1.stack_id

select
t.node_id as nodeId,
t.warning_type as warningType,
t.warning_grade as warningGrade,
t.warning_val as warningVal,
t.principal_name as principalName,
t.siteName as siteName,
t.deal_suggestion as dealSuggestion,
t.deal_time as dealTime,
t.remark as remark
from(
select
t1.node_id,t1.warning_type,t1.warning_grade,t1.warning_val,t1.principal_name,t1.deal_suggestion,t1.deal_time,t1.remark,
t2.site_name as siteName
from tb_early_warning t1
left join tb_ware_area t2 on t2.id = t1.area_id
where t1.is_deal = '1'
and t1.area_id = #{earlyWarningDto.stackId}
and t1.warning_type = #{earlyWarningDto.warningType}
and t1.warning_grade = #{earlyWarningDto.warningGrade}
and t1.node_id = #{earlyWarningDto.nodeId}
and t1.principal_name = #{earlyWarningDto.principalName}
and t1.deal_time >= #{earlyWarningDto.startTime}
and t1.deal_time <= #{earlyWarningDto.endTime}
ORDER BY t1.area_id
) t union
select
t3.node_id as nodeId,
t3.warning_type as warningType,
t3.warning_grade as warningGrade,
t3.warning_val as warningVal,
t3.principal_name as principalName,
t3.siteName as siteName,
t3.deal_suggestion as dealSuggestion,
t3.deal_time as dealTime,
t3.remark as remark
from(
select
t4.node_id,t4.warning_type,t4.warning_grade,t4.warning_val,t4.principal_name,t4.deal_suggestion,t4.deal_time,t4.remark,
t5.site_name as siteName
from tb_early_warning t4
left join tb_stack t5 on t5.id = t4.stack_id
where t4.is_deal = '1'

    and t4.stack_id in #{id}

and t4.warning_type = #{earlyWarningDto.warningType}
and t4.warning_grade = #{earlyWarningDto.warningGrade}
and t4.node_id = #{earlyWarningDto.nodeId}
and t4.principal_name = #{earlyWarningDto.principalName}
and t4.deal_time >= #{earlyWarningDto.startTime}
and t4.deal_time <= #{earlyWarningDto.endTime}
ORDER BY t4.stack_id
) t3

SELECT COUNT(t.id) FROM
(select id from tb_early_warning where 1=1
and area_id = #{earlyWarningDto.stackId}
and warning_type = #{earlyWarningDto.warningType}
and principal_name = #{earlyWarningDto.principalName}
and deal_time >= #{earlyWarningDto.startTime}
and deal_time <= #{earlyWarningDto.endTime}
union
select id from tb_early_warning where 1=1

    and stack_id in #{id}

and warning_type = #{earlyWarningDto.warningType}
and principal_name = #{earlyWarningDto.principalName}
and deal_time >= #{earlyWarningDto.startTime}
and deal_time <= #{earlyWarningDto.endTime}
) t

SELECT t.warning_type as warningType,truncate(COUNT(t.id)/#{earlyWarningDto.count},2) as percentage FROM
(select id,warning_type from tb_early_warning where 1=1
and area_id = #{earlyWarningDto.stackId}
and warning_type = #{earlyWarningDto.warningType}
and principal_name = #{earlyWarningDto.principalName}
and deal_time >= #{earlyWarningDto.startTime}
and deal_time <= #{earlyWarningDto.endTime}
union
select id,warning_type from tb_early_warning where 1=1

    and stack_id in #{id}

and warning_type = #{earlyWarningDto.warningType}
and principal_name = #{earlyWarningDto.principalName}
and deal_time >= #{earlyWarningDto.startTime}
and deal_time <= #{earlyWarningDto.endTime}
) t group by t.warning_type

SELECT t.is_deal as deal,truncate(COUNT(t.id)/#{earlyWarningDto.count},2) as percentage FROM
(select id,is_deal from tb_early_warning where 1=1
and area_id = #{earlyWarningDto.stackId}
and warning_type = #{earlyWarningDto.warningType}
and principal_name = #{earlyWarningDto.principalName}
and deal_time >= #{earlyWarningDto.startTime}
and deal_time <= #{earlyWarningDto.endTime}
union
select id,is_deal from tb_early_warning where 1=1

    and stack_id in #{id}

and warning_type = #{earlyWarningDto.warningType}
and principal_name = #{earlyWarningDto.principalName}
and deal_time >= #{earlyWarningDto.startTime}
and deal_time <= #{earlyWarningDto.endTime}
) t group by t.is_deal

SELECT
(CASE #{earlyWarningDto.dayType}
WHEN '1' THEN DATE_FORMAT(t.deal_time,'%m%d')
WHEN '2' THEN DATE_FORMAT(t.deal_time,'%Y%u') - DATE_FORMAT(#{earlyWarningDto.startTime},'%Y%u') + 1
WHEN '3' THEN DATE_FORMAT(t.deal_time,'%Y%m')
WHEN '4' THEN DATE_FORMAT(t.deal_time,'%Y') END) as dayType,
COUNT(id) as count FROM
(select id,deal_time from tb_early_warning where 1=1
and area_id = #{earlyWarningDto.stackId}
and warning_type = #{earlyWarningDto.warningType}
and principal_name = #{earlyWarningDto.principalName}
and deal_time >= #{earlyWarningDto.startTime}
and deal_time <= #{earlyWarningDto.endTime}
union
select id,deal_time from tb_early_warning where 1=1

    and stack_id in #{id}

and warning_type = #{earlyWarningDto.warningType}
and principal_name = #{earlyWarningDto.principalName}
and deal_time >= #{earlyWarningDto.startTime}
and deal_time <= #{earlyWarningDto.endTime}
) t group by
dayType

SELECT
t.is_deal as deal,
(CASE #{earlyWarningDto.dayType}
WHEN '1' THEN DATE_FORMAT(t.deal_time,'%m%d')
WHEN '2' THEN DATE_FORMAT(t.deal_time,'%Y%u') - DATE_FORMAT(#{earlyWarningDto.startTime},'%Y%u') + 1
WHEN '3' THEN DATE_FORMAT(t.deal_time,'%Y%m')
WHEN '4' THEN DATE_FORMAT(t.deal_time,'%Y') END) AS dayType,
COUNT(id) AS count FROM
(select id,deal_time,is_deal from tb_early_warning where 1=1
and area_id = #{earlyWarningDto.stackId}
and warning_type = #{earlyWarningDto.warningType}
and principal_name = #{earlyWarningDto.principalName}
and deal_time >= #{earlyWarningDto.startTime}
and deal_time <= #{earlyWarningDto.endTime}
union
select id,deal_time,is_deal from tb_early_warning where 1=1

    and stack_id in #{id}

and warning_type = #{earlyWarningDto.warningType}
and principal_name = #{earlyWarningDto.principalName}
and deal_time >= #{earlyWarningDto.startTime}
and deal_time <= #{earlyWarningDto.endTime}
) t
GROUP BY
dayType,t.is_deal ORDER BY dayType
